{
  "name": "工业相机",
  "name_en": "GenICam camera",
  "manufacturer": "",
  "description": "一种用于实验成像和机器视觉采集的数字相机，可连续或触发采集图像，并可调曝光时间、增益、帧率、像素格式和采集区域，常用于显微观察、定位检测和通用视觉测量。",
  "description_en": "A digital machine-vision camera for laboratory imaging and visual data acquisition. It supports continuous or triggered image capture and allows adjustment of exposure time, gain, frame rate, pixel format, and acquisition region, making it suitable for microscopy, alignment, inspection, and general imaging measurements.",
  "tag_hints": [
    "machine vision imaging",
    "triggered image acquisition",
    "GenICam compatible camera",
    "ROI control",
    "exposure and gain control",
    "frame rate control",
    "laboratory imaging"
  ],
  "actions": [
    {
      "action_name": "auto-create_buffers",
      "description": "为图像采集流分配缓冲区",
      "description_en": "allocate buffers for image acquisition"
    },
    {
      "action_name": "auto-try_get_frame",
      "description": "尝试获取最新图像帧",
      "description_en": "try to get the latest image frame"
    },
