      "description": "获取最新图像帧",
      "description_en": "get the latest image frame"
    },
    {
      "action_name": "auto-trigger",
      "description": "触发相机采集一帧图像",
      "description_en": "trigger the camera to acquire one image"
    },
    {
      "action_name": "auto-get_device",
      "description": "获取已连接相机设备",
      "description_en": "get the connected camera device"
    },
    {
      "action_name": "auto-get_sensor_size",
      "description": "获取传感器尺寸",
      "description_en": "get sensor size"
    },
    {
      "action_name": "auto-get_region",
      "description": "获取图像采集区域",
      "description_en": "get the image acquisition region"
    },
    {
      "action_name": "auto-set_region",
      "description": "设置图像采集区域",
      "description_en": "set the image acquisition region"
    },
    {
      "action_name": "auto-get_exposure_time",
      "description": "获取曝光时间",
      "description_en": "get exposure time"
    },
    {
      "action_name": "auto-get_payload",
      "description": "获取图像载荷大小",
      "description_en": "get image payload size"
    },
    {
      "action_name": "auto-get_frame_rate",
      "description": "获取帧率",
      "description_en": "get frame rate"
    },
    {
      "action_name": "auto-set_frame_rate",
      "description": "设置帧率",
      "description_en": "set frame rate"
    },
    {
      "action_name": "auto-get_gain",
      "description": "获取增益",
      "description_en": "get gain"
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置增益",
      "description_en": "set gain"
    },
    {
      "action_name": "auto-get_vendor_name",
      "description": "获取厂商名称",
      "description_en": "get vendor name"
    },
    {
      "action_name": "auto-get_model_name",
      "description": "获取型号名称",
      "description_en": "get model name"
    },
    {
      "action_name": "auto-get_device_id",
      "description": "获取设备标识",
      "description_en": "get device ID"
    },
    {
      "action_name": "auto-set_acquisition_mode",
      "description": "设置采集模式",
      "description_en": "set acquisition mode"
    },
    {
      "action_name": "auto-set_trigger_source",
      "description": "设置触发源",
      "description_en": "set trigger source"
    },
    {
      "action_name": "auto-get_trigger_source",
      "description": "获取触发源",
      "description_en": "get trigger source"
    },
    {
      "action_name": "auto-start_acquisition",
      "description": "开始图像采集",
      "description_en": "start image acquisition"
    },
    {
      "action_name": "auto-start_acquisition_trigger",
      "description": "开始触发采集",
      "description_en": "start triggered acquisition"
    },
    {
      "action_name": "auto-start_acquisition_continuous",
      "description": "开始连续采集",
      "description_en": "start continuous acquisition"
    },
    {
      "action_name": "auto-stop_acquisition",
      "description": "停止图像采集",
      "description_en": "stop image acquisition"
    },
    {
      "action_name": "auto-create_stream",
      "description": "创建图像采集数据流",
      "description_en": "create an image acquisition stream"
    },
    {
      "action_name": "auto-get_pixel_format_as_string",
      "description": "获取像素格式",
      "description_en": "get pixel format"
    },
    {
      "action_name": "auto-cleanup",
      "description": "释放相机资源",
      "description_en": "release camera resources"
    }
  ]
}

